from typing import Any
import csv
import io

REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def _read_rows(source, filename=None):
    """Yield (row_number, list_of_str_cells) from a CSV or XLSX upload.

    `source` may be a file path, raw bytes, or a binary/text file object.
    The format is chosen from the filename extension, else sniffed (XLSX = zip).
    """
    if isinstance(source, str):
        name = filename or source
        with open(source, 'rb') as fh:
            data = fh.read()
    elif isinstance(source, bytes):
        name, data = filename or '', source
    else:
        name = filename or getattr(source, 'name', '')
        data = source.read()
    if isinstance(data, str):
        data = data.encode('utf-8')

    lowered = str(name).lower()
    is_xlsx = lowered.endswith(('.xlsx', '.xlsm')) or (
        not lowered.endswith('.csv') and data[:2] == b'PK')

    if is_xlsx:
        from openpyxl import load_workbook
        wb = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
        try:
            for number, values in enumerate(wb.active.iter_rows(values_only=True), 1):
                yield number, ['' if v is None else str(v) for v in values]
        finally:
            wb.close()
    else:
        reader = csv.reader(io.StringIO(data.decode('utf-8-sig')))
        for values in reader:
            yield reader.line_num, values


def validate_users_upload(source, filename=None, max_rows: int = MAX_ROWS) -> list[dict[str, Any]]:
    """Validate an uploaded users spreadsheet (CSV or XLSX).

    Returns a list of bad rows: {"row": <row number in the file>, "errors": [reasons]}.
    All problems for every row are reported; validation never stops at the first error.
    Cell values are not echoed back in messages.
    """
    header = None
    index = {}
    errors, seen, count = [], set(), 0

    for number, values in _read_rows(source, filename):
        blank = not any(v.strip() for v in values)
        if header is None:
            if blank:
                continue
            header = [v.strip().lstrip('\ufeff').lower() for v in values]
            missing = [c for c in REQUIRED_COLUMNS if c not in header]
            if missing:
                return [{'row': number, 'errors': [f"missing columns: {', '.join(missing)}"]}]
            index = {c: header.index(c) for c in REQUIRED_COLUMNS}
            continue
        if blank:
            continue

        count += 1
        if count > max_rows:
            errors.append({'row': number, 'errors': [f'more than {max_rows} rows; stopped']})
            break

        def cell(col):
            i = index[col]
            return values[i].strip() if i < len(values) else ''

        name = cell('name')
        email = cell('email').lower()
        role = cell('role').lower()
        local, _, domain = email.partition('@')

        problems = []
        if not name:
            problems.append('name is required')
        if not email:
            problems.append('email is required')
        elif (len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email
              or '@' in domain or '.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        else:
            seen.add(email)
        if not role:
            problems.append('role is required')
        elif role not in VALID_ROLES:
            problems.append(f"role must be one of: {', '.join(VALID_ROLES)}")
        if len(values) > len(header) and any(v.strip() for v in values[len(header):]):
            problems.append('too many fields')

        if problems:
            errors.append({'row': number, 'errors': problems})

    if header is None:
        return [{'row': 1, 'errors': ['file is empty']}]
    return errors

